      ta: "இதர பிற்படுத்தப்பட்ட வகுப்பினரின் (OBC) பொருளாதார மேம்பாட்டிற்காக அர்ப்பணிக்கப்பட்ட மத்திய அரசு நிறுவனம். திறன் பயிற்சி மற்றும் சுயதொழில் நிதியுதவி வழங்குகிறது.",
