      ta: "தொழில்நுட்ப டிப்ளமோ, ஐடிஐ மற்றும் பாலிடெக்னிக் படிப்புகளுக்கு ஆண்டுக்கு ₹75,000 முதல் ₹1,25,000 வரை நேரடி வங்கிப் பரிமாற்ற (DBT) உதவித்தொகை.",
