      kn: "ತಾಂತ್ರಿಕ ಡಿಪ್ಲೊಮಾ, ಐಟಿಐ ಮತ್ತು ಪಾಲಿಟೆಕ್ನಿಕ್ ಅಧ್ಯಯನಗಳಿಗಾಗಿ ವರ್ಷಕ್ಕೆ ₹75,000 ರಿಂದ ₹1,25,000 ನೇರ ಬ್ಯಾಂಕ್ ವರ್ಗಾವಣೆ (ಡಿಬಿಟಿ) ವಿದ್ಯಾರ್ಥಿವೇತನ.",
