      bn: "কারিগরি ডিপ্লোমা, আইটিআই এবং পলিটেকনিক পড়াশোনার জন্য বছরে ₹৭৫,০০০ থেকে ₹১,২৫,০০০ সরাসরি ব্যাংক ট্রান্সফার (ডিবিটি) স্কলারশিপ।",
      mr: "तांत्रिक डिप्लोमा, आयटीआय आणि पॉलिटेक्निक शिक्षणासाठी दरवर्षी ₹७५,००० ते ₹१,२५,००० ची थेट बँक हस्तांतरण (डीबीटी) शिष्यवृत्ती.",
      gu: "ટેકનિકલ ડિપ્લોમા, ITI અને પોલિટેકનિક અભ્યાસ માટે વાર્ષિક ₹75,000 થી ₹1,25,000 ની ડાયરેક્ટ બેંક ટ્રાન્સફર (DBT) શિષ્યવૃત્તિ.",
      pa: "ਤਕਨੀਕੀ ਡਿਪਲੋਮਾ, ਆਈਟੀਆਈ ਅਤੇ ਪੌਲੀਟੈਕਨਿਕ ਅਧਿਐਨਾਂ ਲਈ ਸਾਲਾਨਾ ₹75,000 ਤੋਂ ₹1,25,000 ਦੀ ਸਿੱਧੀ ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ (DBT) ਸਕਾਲਰਸ਼ਿਪ।",
      or: "ବୈଷୟିକ ଡିପ୍ଲୋମା, ITI ଏବଂ ପଲିଟେକ୍ନିକ୍ ପାଇଁ ବାର୍ଷିକ ₹୭୫,୦୦୦ ରୁ ₹୧,୨୫,୦୦୦ ପ୍ରତ୍ୟକ୍ଷ ବ୍ୟାଙ୍କ ଜମା (DBT) ଛାତ୍ରବୃତ୍ତି।",
      as: "কাৰিকৰী ডিপ্ল’মা, ITI আৰু পলিটেকনিক শিক্ষাৰ বাবে বছৰি ₹৭৫,০০০ ৰ পৰা ₹১,২৫,০০০ পোনপটীয়া বেংক ট্ৰান্সফাৰ (DBT) বৃত্তি।",
      ur: "تکنیکی ڈپلومہ، ITI اور پولی ٹیکنک تعلیم کے لیے سالانہ ₹75,000 تا ₹1,25,000 براہ راست بینک ٹرانسفر (DBT) اسکالرشپ۔"
