      gu: "ટેકનિકલ એન્જિનિયરિંગ ડિપ્લોમા કરતા ઓબીસી વિદ્યાર્થીઓ માટે પ્રાથમિકતા ક્વોટા.",
      pa: "ਤਕਨੀਕੀ ਇੰਜੀਨੀਅਰਿੰਗ ਡਿਪਲੋਮਾ ਕਰ ਰਹੇ ਓਬੀਸੀ ਵਿਦਿਆਰਥੀਆਂ ਲਈ ਤਰਜੀਹੀ ਕੋਟਾ।",
      or: "ଇଞ୍ଜିନିୟରିଂ ଡିପ୍ଲୋମା କରୁଥିବା ଓବିସି (OBC) ଛାତ୍ରଛାତ୍ରୀଙ୍କ ପାଇଁ ଅଗ୍ରାଧିକାର କୋଟା।",
      as: "কাৰিকৰী অভিযান্ত্ৰিক ডিপ্ল’মা পঢ়ি থকা অ’বিচি ছাত্ৰ-ছাত্ৰীৰ বাবে অগ্ৰাধিকাৰ কোটা।",
