      ta: "கார்ப்பரேட் நிறுவனங்களில் ஊதியத்துடன் கூடிய தொழில்பயிற்சி மூலம் இளைஞர்களுக்கு வேலைவாய்ப்பை உறுதி செய்யும் தேசிய திட்டம்.",
      te: "కార్పొరేట్ చెల్లింపు అప్రెంటిస్‌షిప్‌ల ద్వారా యువతకు ఉపాధి అవకాశాలను సులభతరం చేసే జాతీయ పథకం.",
      kn: "ಕಾರ್ಪೊರೇಟ್ ಪಾವತಿಸಿದ ಅಪ್ರೆಂಟಿಸ್‌ಶಿಪ್‌ಗಳ ಮೂಲಕ ಉದ್ಯೋಗ ಪ್ರವೇಶವನ್ನು ಸುಗಮಗೊಳಿಸುವ ರಾಷ್ಟ್ರೀಯ ಯೋಜನೆ.",
