        "bn": "বাজার-সংযুক্ত উপজাতি উদ্যোক্তা প্রোগ্রাম যা ট্রাইবস ইন্ডিয়া আউটলেটগুলির মাধ্যমে আধুনিক সরঞ্জাম ও প্রিমিয়াম ব্র্যান্ডিং সহ ঐতিহ্যবাহী সংগ্রাহক ও কারিগরদের ক্ষুদ্র প্রস্তুতকারকে রূপান্তরিত করে।",
