        "gu": "માર્કેટ-લિંક્ડ આદિવાસી સાહસિકતા કાર્યક્રમ જે પરંપરાગત સંગ્રહકો અને કારીગરોને ટ્રાઇબ્સ ઇન્ડિયા આઉટલેટ્સ દ્વારા આધુનિક સાધનો સાથે સૂક્ષ્મ-ઉત્પાદકોમાં અપગ્રેડ કરે છે.",
        "pa": "ਮਾਰਕੀਟ-ਲਿੰਕਡ ਕਬਾਇਲੀ ਉੱਦਮਤਾ ਪ੍ਰੋਗਰਾਮ ਜੋ ਟ੍ਰਾਈਬਜ਼ ਇੰਡੀਆ ਆਊਟਲੈਟਸ ਰਾਹੀਂ ਆਧੁਨਿਕ ਉਪਕਰਨਾਂ ਨਾਲ ਰਵਾਇਤੀ ਕਾਰੀਗਰਾਂ ਨੂੰ ਸੂਖਮ-ਨਿਰਮਾਤਾਵਾਂ ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰਦਾ ਹੈ।",
