        "as": "বজাৰ-সংযুক্ত জনজাতীয় উদ্যোগী কাৰ্যসূচী যিয়ে পৰম্পৰাগত সংগ্ৰাহক আৰু শিল্পীসকলক আধুনিক সঁজুলি আৰু Tribes India বিপনীৰ জৰিয়তে ক্ষুদ্ৰ উৎপাদক হিচাপে উন্নীত কৰে।",
